/**
 * EasyQRCode / Minimal QR Code Canvas Generator for OmniGuard
 */
var QRCode;
(function(){
    function QRBitBuffer(){this.buffer=[];this.length=0;}
    QRBitBuffer.prototype={get:function(index){var bufIndex=Math.floor(index/8);return((this.buffer[bufIndex]>>>(7-index%8))&1)==1;},put:function(num,length){for(var i=0;i<length;i++){this.putBit(((num>>>(length-i-1))&1)==1);}},putBit:function(bit){var bufIndex=Math.floor(this.length/8);if(this.buffer.length<=bufIndex){this.buffer.push(0);}if(bit){this.buffer[bufIndex]|=(0x80>>>(this.length%8));}this.length++;}};
    var QRPolynomial={glog:function(n){if(n<1){throw new Error("glog("+n+")");}return QRMath.glog(n);},gexp:function(n){while(n<0){n+=255;}while(n>=256){n-=255;}return QRMath.gexp(n);}};
    var QRMath={glog:function(n){if(n<1){throw new Error("glog("+n+")");}return QRMath.LOG_TABLE[n];},gexp:function(n){while(n<0){n+=255;}while(n>=256){n-=255;}return QRMath.EXP_TABLE[n];},EXP_TABLE:new Array(256),LOG_TABLE:new Array(256)};
    for(var i=0;i<8;i++){QRMath.EXP_TABLE[i]=1<<i;}
    for(var i=8;i<256;i++){QRMath.EXP_TABLE[i]=QRMath.EXP_TABLE[i-4]^QRMath.EXP_TABLE[i-5]^QRMath.EXP_TABLE[i-6]^QRMath.EXP_TABLE[i-8];}
    for(var i=0;i<255;i++){QRMath.LOG_TABLE[QRMath.EXP_TABLE[i]]=i;}

    function QRRSBlock(totalCount,dataCount){this.totalCount=totalCount;this.dataCount=dataCount;}
    QRRSBlock.RS_BLOCK_TABLE=[[1,26,19],[1,44,34],[1,70,55],[1,100,80],[1,134,108],[2,86,68],[2,98,78],[2,121,97],[2,146,116],[2,86,68]];
    QRRSBlock.getRSBlocks=function(typeNumber){var rsBlock=QRRSBlock.RS_BLOCK_TABLE[(typeNumber-1)*4+1]||[1,44,34];return [new QRRSBlock(rsBlock[1],rsBlock[2])];};

    function QRCodeModel(typeNumber,errorCorrectLevel){this.typeNumber=typeNumber;this.errorCorrectLevel=errorCorrectLevel;this.modules=null;this.moduleCount=0;this.dataList=[];}
    QRCodeModel.prototype={
        addData:function(data){this.dataList.push(data);},
        isDark:function(row,col){return this.modules[row][col];},
        getModuleCount:function(){return this.moduleCount;},
        make:function(){
            this.moduleCount=this.typeNumber*4+17;
            this.modules=new Array(this.moduleCount);
            for(var row=0;row<this.moduleCount;row++){this.modules[row]=new Array(this.moduleCount);for(var col=0;col<this.moduleCount;col++){this.modules[row][col]=null;}}
            this.setupPositionProbePattern(0,0);
            this.setupPositionProbePattern(this.moduleCount-7,0);
            this.setupPositionProbePattern(0,this.moduleCount-7);
            this.setupTimingPattern();
            var buffer=new QRBitBuffer();
            for(var i=0;i<this.dataList.length;i++){
                var data=this.dataList[i];
                buffer.put(4,4); // 8-bit byte mode
                buffer.put(data.length,8);
                for(var j=0;j<data.length;j++){buffer.put(data.charCodeAt(j),8);}
            }
            buffer.put(0,4);
            while(buffer.length%8!=0){buffer.putBit(false);}
            var bytes=[];
            for(var i=0;i<buffer.length/8;i++){var b=0;for(var j=0;j<8;j++){if(buffer.get(i*8+j)){b|=(1<<(7-j));}}bytes.push(b);}
            var totalDataCount=34;
            var padBytes=[0xEC,0x11];
            var padIndex=0;
            while(bytes.length<totalDataCount){bytes.push(padBytes[padIndex%2]);padIndex++;}
            var row=this.moduleCount-1;var col=this.moduleCount-1;var dir=-1;var byteIndex=0;var bitIndex=7;
            while(col>0){
                if(col==6)col--;
                while(true){
                    for(var c=0;c<2;c++){
                        if(this.modules[row][col-c]===null){
                            var dark=false;
                            if(byteIndex<bytes.length){dark=((bytes[byteIndex]>>bitIndex)&1)==1;}
                            if((row+col-c)%2==0){dark=!dark;}
                            this.modules[row][col-c]=dark;
                            bitIndex--;
                            if(bitIndex<0){byteIndex++;bitIndex=7;}
                        }
                    }
                    row+=dir;
                    if(row<0||this.moduleCount<=row){row-=dir;dir=-dir;break;}
                }
                col-=2;
            }
        },
        setupPositionProbePattern:function(row,col){
            for(var r=-1;r<=7;r++){
                if(row+r<=-1||this.moduleCount<=row+r)continue;
                for(var c=-1;c<=7;c++){
                    if(col+c<=-1||this.moduleCount<=col+c)continue;
                    if((0<=r&&r<=6&&(c==0||c==6))||(0<=c&&c<=6&&(r==0||r==6))||(2<=r&&r<=4&&2<=c&&c<=4)){
                        this.modules[row+r][col+c]=true;
                    }else{this.modules[row+r][col+c]=false;}
                }
            }
        },
        setupTimingPattern:function(){
            for(var r=8;r<this.moduleCount-8;r++){if(this.modules[r][6]!==null)continue;this.modules[r][6]=(r%2==0);}
            for(var c=8;c<this.moduleCount-8;c++){if(this.modules[6][c]!==null)continue;this.modules[6][c]=(c%2==0);}
        }
    };

    QRCode=function(target,options){
        if(typeof options==="string"){options={text:options};}
        this.options={width:options.width||220,height:options.height||220,text:options.text||""};
        this.target=typeof target==="string"?document.getElementById(target):target;
        if(this.target){this.makeCode(this.options.text);}
    };
    QRCode.prototype.makeCode=function(text){
        var qrcode=new QRCodeModel(4,1);
        qrcode.addData(text);
        qrcode.make();
        var canvas=document.createElement("canvas");
        canvas.width=this.options.width;
        canvas.height=this.options.height;
        var ctx=canvas.getContext("2d");
        var count=qrcode.getModuleCount();
        var tileW=this.options.width/count;
        var tileH=this.options.height/count;
        ctx.fillStyle="#ffffff";
        ctx.fillRect(0,0,this.options.width,this.options.height);
        ctx.fillStyle="#0f172a";
        for(var row=0;row<count;row++){
            for(var col=0;col<count;col++){
                if(qrcode.isDark(row,col)){
                    ctx.fillRect(Math.round(col*tileW),Math.round(row*tileH),Math.ceil(tileW),Math.ceil(tileH));
                }
            }
        }
        this.target.innerHTML="";
        this.target.appendChild(canvas);
    };
})();
